".page {
  min-height: 100vh;
  min-width: 100vw;
  display: flex;
  flex-direction: column;
  align-items: center;
  /* clip instead of hidden so negative-margin grid bleed works */
  overflow-x: clip;
}

.menu-main {
  padding: 32px 40px;
  display: flex;
  flex-direction: column;
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.menu-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.menu-header .eyebrow {
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--color-text-placeholder);
}

.menu-header h1 {
  font-size: 28px;
  font-weight: 800;
  color: var(--color-text);
  margin: 0;
}

/* Responsive */
@media (max-width: 600px) {
  .menu-main {
    padding: 20px 16px;
  }
}
"

".daily-options {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
}

.daily-options h2 {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
}

.daily-options-grid {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  /* bleed past parent padding so first/last cards aren't clipped */
  margin-left: -40px;
  margin-right: -40px;
  padding-left: 40px;
  padding-right: 40px;
}

.daily-options-grid::-webkit-scrollbar {
  display: none;
}

/* Floating cart bar */
.cart-float {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-text);
  color: #fff;
  padding: 12px 20px 12px 24px;
  border-radius: var(--radius-pill);
  display: flex;
  align-items: center;
  gap: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
  z-index: 50;
  animation: cart-slide-up 0.25s ease-out;
}

@keyframes cart-slide-up {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(16px);
  }

  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

.cart-float-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.cart-float-count {
  font-size: 12px;
  font-weight: 500;
  opacity: 0.8;
}

.cart-float-total {
  font-size: 17px;
  font-weight: 800;
}

.cart-float-btn {
  background: #fff;
  color: var(--color-text);
  font-size: 14px;
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  white-space: nowrap;
}

.cart-float-btn:hover {
  background: var(--color-surface-muted);
}

@media (max-width: 600px) {
  .daily-options-grid {
    margin-left: -16px;
    margin-right: -16px;
    padding-left: 16px;
    padding-right: 16px;
  }
}
"

