import { meals, categories } from "../../data/mockData";
import "./FullMenu.css";
import MealOptionCard from "../MealOptionCard/MealOptionCard";

function FullMenu() {
  const [activeCategory, setActiveCategory] = useState("All");
  const [selections, setSelections] = useState({});

  const filteredMeals =
    activeCategory === "All"
      ? meals
      : meals.filter((meal) => meal.category === activeCategory);

  return (
    <section className="full-menu">
      <h2>Full Menu</h2>
      <div className="category-bar">
        {categories.map((cat) => (
          <button
            key={cat.id}
            className={`category-btn ${activeCategory === cat.name ? "active" : ""}`}
            onClick={() => setActiveCategory(cat.name)}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {filteredMeals.length > 0 ? (
        <div className="meal-list">
          {filteredMeals.map((meal) => (
            <MealOptionCard
              key={meal.id}
              option={meal}
              qty={selections[meal.id] || 0}
              setSelections={setSelections}
            />
          ))}
        </div>
      ) : (
        <div className="empty-state">
          <p>No meals available in this category.</p>
        </div>
      )}
    </section>
  );
}

export default FullMenu;"

