".full-menu {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.full-menu h2 {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
}

.category-bar {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.category-btn {
  padding: 10px 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-muted);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s;
}

.category-btn:hover {
  border-color: var(--color-border-strong);
  color: var(--color-text);
}

.category-btn.active {
  background: var(--color-text);
  color: #fff;
  border-color: var(--color-text);
}

/* Card Grid Layout */
.meal-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--color-text-muted);
  font-size: 15px;
}
"

